									+ LEx.util.Format
											.formatDate(ret.data[0].SEND_TIME)
									+ "]" + t,
							content : LEx.htmlDecode(ret.data[0].CONTENT)
						});
			}
		}
	}
	command.execute('getLastList', false);
}"}

