{"_best_guess": {"file": "captures/icity/public/scripts/common.js", "start_offset": 5523, "end_offset": 7443}, "_best_guess_score": -782, "name": "initNavigation", "file": "captures/icity/public/scripts/common.js", "start_offset": 5523, "end_offset": 7443, "code": "function initNavigation() {
