{"_best_guess": {"file": "captures/icity/public/scripts/common.js", "start_offset": 8474, "end_offset": 9690}, "_best_guess_score": -147, "name": "mDialog", "file": "captures/icity/public/scripts/common.js", "start_offset": 8474, "end_offset": 9690, "code": "function mDialog(obj) {
	// if(!isNotNull(obj.id)){
	// obj.id = "operationWindow";
	// }
	if (!isNotNull(obj.title)) {
		obj.title = "操作";
	}
	if (!isNotNull(obj.buttonName)) {// 按钮名称
		obj.buttonName = "保存";
	}
	if (!isNotNull(obj.width)) {// 宽度
		obj.width = 800;
	}
	if (!isNotNull(obj.height)) {// 高度
		obj.height = 280;
	}
	if (!isNotNull(obj.save)) {// 高度
		obj.save = 'true';
	}
	if (!isNotNull(obj.del)) {// 高度
		obj.del = 'true';
	}
	obj.button = [];
	if (obj.button.length == 0) {// 如果页面未定义button，采用默认
		if (!isNotNull(obj.qmName)) {// 回调执行方法
			obj.qmName = "onQuery()";
		}
		if (!isNotNull(obj.pmName)) {// 弹出框执行具体操作的方法
			obj.pmName = "postData()";
		}
		if (obj.save == 'true') {
			obj.button.push({
				name : obj.buttonName,
				callback : function() {
					var iframe = this.iframe.contentWindow;
					if (!iframe.document.body) {
						LEx.alert('内容还没加载完毕呢');
						return false;
					}
					if (iframe.eval(obj.pmName)) {
						eval(obj.qmName);
						return true;
					} else {
						return false;
					}
				},
				focus : true
			});
		}
		if (obj.del == 'true') {
			obj.button.push({
				name : '关闭'
			});
		}
	}
	LEx.dialog(obj);
}"}

